        Drug(
            id = "d_atracurium",
            genericName = "Atracurium Besylate",
            system = "Anesthesiology & Perioperative",
            drugClass = "Non-Depolarizing Neuromuscular Blocking Agent (NMBA) / Benzylisoquinolinium Paralytic",
            blackBoxWarning = "Administer under the supervision of skilled personnel equipped with full resuscitation and artificial ventilation equipment. Check reversal objectively prior to tracheal extubation.",
            indications = "Skeletal muscle relaxation for Endotracheal Intubation and maintenance of General Anesthesia; DRUG OF CHOICE in patients with severe Renal Failure (ESRD / Hemodialysis) or Hepatic Failure (Cirrhosis / Fulminant Hepatitis) due to organ-independent elimination.",
            doses = "Endotracheal Intubation:\n• Adult: 0.4 to 0.5 mg/kg IV bolus over 60 seconds (intubating conditions achieved in 2.0 to 2.5 minutes; duration of surgical relaxation ~20 to 35 minutes).\n• Pediatric (≥2 years): 0.3 to 0.4 mg/kg IV.\n\nIntraoperative Maintenance:\n• Intermittent Boluses: 0.08 to 0.1 mg/kg IV as guided by TOF monitoring (~every 15-25 min).\n• Continuous IV Infusion: 5 to 10 mcg/kg/min (0.3 to 0.6 mg/kg/hour) IV.\n\nReversal:\n• Traditional Reversal: Neostigmine 0.05 mg/kg IV + Glycopyrrolate 0.01 mg/kg IV (or Atropine 0.02 mg/kg) once TOF shows ≥2 twitches. (Note: Sugammadex DOES NOT reverse benzylisoquinolines like atracurium; it only reverses aminosteroids).",
            administration = "Administer intravenously only. SLOW INJECTION over 60 to 75 seconds significantly reduces histamine release and prevents transient hypotension and cutaneous flushing. Store refrigerated at 2°C to 8°C (loses ~5% potency per month at room temperature).",
            timing = "Hospital Operating Room / ICU intravenous administration only (शल्यक्रिया कक्ष वा ICU मा मात्र नसाबाट दिने).",
            specialInstructions = "ORGAN-INDEPENDENT DEGRADATION: Completely broken down in blood and tissues by spontaneous, non-enzymatic chemical cleavage at physiological pH and temperature (Hofmann Elimination) and non-specific ester hydrolysis. Organ failure (liver or kidney shutdown) DOES NOT prolong duration of action.",
            pkPd = "Bis-quaternary benzylisoquinolinium diester. Intermediate duration of action. Highly hydrophilic. Unique dual elimination pathway: 1) Hofmann Elimination (spontaneous non-enzymatic chemical degradation into laudanosine and a monoquaternary acrylate at body pH 7.4 and temp 37°C, accounting for ~30-40%), and 2) Non-specific plasma ester hydrolysis (cleaved by esterases unrelated to pseudocholinesterase, accounting for ~60%). Laudanosine is metabolized by the liver; at extremely high continuous doses over days in the ICU, laudanosine accumulation can theoretically cause CNS excitation and seizures. Elimination half-life ~20 minutes.",
            renalAdj = "NO DOSAGE ADJUSTMENT NEEDED across all stages of renal disease, severe CKD, and ESRD on hemodialysis (ideal first-line paralytic in renal failure).",
            hepaticAdj = "NO DOSAGE ADJUSTMENT NEEDED in liver cirrhosis or end-stage liver failure.",
            pregnancy = "Category C. Highly ionized; does not cross the placental barrier in significant amounts. Safe for cesarean delivery.",
            lactation = "Safe during breastfeeding once patient recovers.",
            sideEffects = "Histamine release (in up to 20% with rapid IV bolus: transient skin flushing of face/neck, mild hypotension, sinus tachycardia, rare bronchospasm in reactive airways), laudanosine accumulation with prolonged multi-day ICU infusions, residual neuromuscular block.",
