        // 10. Sugammadex Sodium
        Drug(
            id = "d_sugammadex",
            genericName = "Sugammadex Sodium",
            system = "Anesthesiology & Perioperative",
            drugClass = "Selective Relaxant Binding Agent (SRBA) / Modified Gamma-Cyclodextrin",
            blackBoxWarning = "ANAPHYLAXIS & HYPERSENSITIVITY WARNING: Severe hypersensitivity and anaphylactic reactions (bronchospasm, angioedema, hypotension, circulatory collapse) reported in up to 0.3% of healthy volunteers. Be prepared to treat acute anaphylaxis immediately with Epinephrine. MARKED BRADYCARDIA: Profound bradycardia, bradyarrhythmias, and cardiac arrest reported within minutes of administration; monitor heart rate continuously and have IV Atropine immediately available.",
            indications = "Routine and Urgent Reversal of Neuromuscular Blockade induced by Rocuronium Bromide or Vecuronium Bromide in adult and pediatric patients (≥2 years); Immediate rescue reversal of profound rocuronium blockade in 'Cannot Intubate, Cannot Oxygenate' (CICO) airway emergencies.",
            doses = "Dosing is based on ACTUAL BODY WEIGHT and DEPTH OF NEUROMUSCULAR BLOCK (guided by peripheral nerve stimulation / TOF):\n\n1. Moderate Block Reversal (TOF shows reappearance of second twitch, T2):\n• 2.0 mg/kg IV single bolus. Reversal to TOF ratio ≥0.90 occurs in ~1.5 to 2 minutes.\n\n2. Deep Block Reversal (TOF count 0, but Post-Tetanic Count [PTC] shows 1 to 2 twitches):\n• 4.0 mg/kg IV single bolus. Reversal occurs in ~2.5 to 3 minutes.\n\n3. Immediate Emergency Rescue Reversal (CICO Scenario - 3 minutes post-1.2 mg/kg Rocuronium RSI):\n• 16.0 mg/kg IV single bolus immediately. Produces rapid complete reversal and return of spontaneous ventilation within ~1.5 to 3 minutes (faster than spontaneous succinylcholine recovery).",
            administration = "Administer as a single rapid intravenous injection over 10 seconds into an existing IV line. Compatible with 0.9% Normal Saline, 5% Dextrose, and Lactated Ringer's.",
            timing = "Hospital Operating Room / ICU intravenous administration only (शल्यक्रिया कक्ष वा ICU मा मात्र नसाबाट दिने).",
            specialInstructions = "HORMONAL CONTRACEPTIVE INTERACTION: Sugammadex binds and encapsulates progesterone and estrogen, mimicking a missed dose of oral contraceptives. Women taking oral contraceptives MUST be instructed to use an additional reliable non-hormonal barrier method (condoms) for the NEXT 7 CONSECUTIVE DAYS.",
            pkPd = "Modified gamma-cyclodextrin with 8 lipophilic interior cavity extensions and negatively charged carboxyl thio-ether side chains. 1:1 molecular encapsulation of rocuronium or vecuronium with extremely high thermodynamic affinity (Ka = 1.79 x 10^7 M^-1). Free rocuronium in plasma drops to near zero within seconds, drawing rocuronium away from the neuromuscular junction into the vascular compartment by concentration gradient. Excreted almost entirely unchanged (>95%) by renal glomerular filtration. Elimination half-life ~2 hours in normal renal function.",
            renalAdj = "Mild to moderate CKD (CrCl 30-80 mL/min): Standard dosing. Severe renal impairment (CrCl <30 mL/min) or ESRD on Hemodialysis: NOT RECOMMENDED (sugammadex-rocuronium complex is not excreted and remains in circulation for days; can be dialyzed using high-flux dialyzers).",
            hepaticAdj = "No dosage adjustment needed (elimination is independent of hepatic metabolism).",
            pregnancy = "Category B. Animal reproduction studies show no teratogenicity; use only if clinical benefit justifies potential risk.",
            lactation = "Excreted in small amounts in animal milk; evaluate benefit-risk balance during breastfeeding.",
            sideEffects = "Transient dysgeusia (metallic or bitter taste in up to 10%), marked sinus bradycardia, hypotension, anaphylaxis/bronchospasm, recurrence of neuromuscular block (recurarization if under-dosed), mild prolongation of prothrombin time (PT/INR) and aPTT for up to 60 minutes (no significant increase in clinical bleeding).",
            priceNpr = "NPR 8,500.00 - 15,000.00 per vial (100 mg/mL: 2 mL = 200 mg / 5 mL = 500 mg)",
            priceInr = "INR 5,500.00 - 9,800.00 per vial",
            brandsNepal = listOf(
                BrandInfo("Bridion-Quest", "Quest Pharmaceuticals", "Injection", "100 mg/mL (2 mL / 5 mL)"),
                BrandInfo("Sugammadex-NPL", "Nepal Pharmaceuticals Lab", "Injection", "100 mg/mL (2 mL)")
            ),
            brandsIndia = listOf(
                BrandInfo("Bridion", "Merck Sharp & Dohme (MSD)", "Injection", "100 mg/mL (2 mL / 5 mL)"),
                BrandInfo("Suganext", "Neon Laboratories", "Injection", "100 mg/mL (2 mL / 5 mL)"),
                BrandInfo("Sugamac", "MacLeods Pharmaceuticals", "Injection", "100 mg/mL (2 mL / 5 mL)"),
                BrandInfo("Gammadex", "Troikaa Pharmaceuticals", "Injection", "100 mg/mL (2 mL)")
            ),
            adultDose = "Moderate block (T2): 2 mg/kg IV. Deep block (PTC 1-2): 4 mg/kg IV. Emergency CICO: 16 mg/kg IV.",
            childDose = "Pediatric (≥2 years): Same as adult weight-based dosing (2 to 4 mg/kg IV).",
            contraindications = "Known severe hypersensitivity to sugammadex or cyclodextrins; severe renal impairment (CrCl <30 mL/min) not on dialysis.",
            modeOfAction = "Forms tight, biologically inactive 1:1 guest-host inclusion complexes by encapsulating the lipophilic steroid core of Rocuronium and Vecuronium inside its central hydrophobic cavity; drastically collapses free drug concentration in plasma, creating an intense concentration gradient that strips muscle relaxant molecules directly off the motor endplate acetylcholine receptors back into circulation.",
            interactions = "Encapsulates and inactivates Oral Contraceptives (patient must use barrier contraception for 7 days); Toremifene and Flucloxacillin can displace rocuronium from sugammadex (monitor for recurarization). If re-curarization is urgently required shortly after sugammadex: use non-steroidal NMBA (Atracurium or Cisatracurium).",
            packSize = "Glass vial of 2 mL (200 mg) or 5 mL (500 mg) sterile solution (100 mg/mL)",
            precautions = "Calculate dose accurately based on ACTUAL body weight. Have Atropine drawn for bradycardia. Advise female patients of childbearing potential on the 7-day backup contraception rule.",
            ddaSchedule = "Schedule Kha (Restricted Specialist Anesthesiology POM)",
            nemlCategory = "NEML: Tertiary Hospital Formulary (Advanced Anesthesia / CICO Emergency)",
            beersCriteriaRisk = null,
            era = "Newer / Modern Standard",
            therapeuticClassTag = "Selective Reversal / Cyclodextrin",
            counselingNepali = "यो शल्यक्रियापछि मांसपेशीलाई सक्रिय बनाउन र होस खुलाउन दिइने आधुनिक औषधि हो। परिवार नियोजनको चक्की खाइरहनु भएको छ भने यो औषधिले ७ दिनसम्म त्यसको प्रभाव घटाउने भएकोले कन्डम जस्ता अन्य साधन प्रयोग गर्नुपर्छ।",
