        // 11. Neostigmine Methylsulfate
        Drug(
            id = "d_neostigmine",
            genericName = "Neostigmine Methylsulfate",
            system = "Anesthesiology & Perioperative",
            drugClass = "Acetylcholinesterase Inhibitor / Traditional Neuromuscular Block Reversal",
            blackBoxWarning = "Administer under experienced anesthesia supervision. SEVERE MUSCARINIC EFFECTS HAZARD: Excessive accumulation of acetylcholine at post-ganglionic parasympathetic sites can cause life-threatening bradycardia, complete heart block, asystole, bronchospasm, and copious airway secretions. MUST ALWAYS BE CO-ADMINISTERED WITH AN ANTIMUSCARINIC AGENT (Glycopyrrolate or Atropine).",
            indications = "Reversal of non-depolarizing neuromuscular blockade (Atracurium, Vecuronium, Rocuronium, Cisatracurium) at the end of surgery once spontaneous recovery has initiated (Train-of-Four shows at least 2 twitches); Symptomatic management of Myasthenia Gravis; Postoperative non-obstructive urinary retention; Ogilvie syndrome (acute colonic pseudo-obstruction).",
            doses = "Reversal of Non-Depolarizing Neuromuscular Blockade:\n• Standard Dose: 0.04 to 0.05 mg/kg IV slow push (typical adult dose: 2.5 mg) up to max 0.07 mg/kg or 5.0 mg total.\n• CO-ADMINISTRATION RATIO WITH ANTIMUSCARINICS:\n  1. With Glycopyrrolate (Preferred - matches neostigmine onset and duration):\n     Neostigmine 0.05 mg/kg (2.5 mg) + Glycopyrrolate 0.01 mg/kg (0.5 mg) IV combined in the same syringe.\n  2. With Atropine (Faster onset, more tachycardia):\n     Neostigmine 0.05 mg/kg (2.5 mg) + Atropine Sulfate 0.02 mg/kg (1.0 to 1.2 mg) IV.\n• Pediatric: 0.04 to 0.05 mg/kg IV with Glycopyrrolate 0.01 mg/kg or Atropine 0.02 mg/kg.",
            administration = "Administer slowly IV over 1 to 2 minutes. NEVER ADMINISTER if there are ZERO twitches on TOF stimulation (cannot reverse intense profound block; neostigmine at profound block depth induces paradoxical channel blockade and weakness).",
            timing = "Hospital Operating Room / PACU intravenous administration only (शल्यक्रिया कक्ष वा रिकभरीमा मात्र नसाबाट दिने).",
            specialInstructions = "Wait for at least 2 twitches (ideally 4 twitches with fade) on TOF peripheral nerve stimulator before giving neostigmine. Peak reversal effect requires 7 to 10 minutes. Objective TOF ratio ≥0.90 must be documented before extubation.",
            pkPd = "Quaternary ammonium carbamate ester. Lipid-insoluble; does not cross the blood-brain barrier. Peak anticholinesterase effect in 7-10 minutes. Bound to serum albumin (~15-25%). Hydrolyzed by plasma and hepatic esterases, and eliminated unchanged by renal tubular secretion (50-70%). Elimination half-life ~50-90 minutes (significantly prolonged in renal failure, matching the prolonged clearance of atracurium/vecuronium).",
            renalAdj = "No dosage reduction needed (clearance of both neostigmine and muscle relaxants are equally prolonged in renal failure).",
            hepaticAdj = "No dosage adjustment needed.",
            pregnancy = "Category C. Does not cross the placenta in significant amounts (quaternary amine); safe for reversal during cesarean delivery.",
            lactation = "Safe during breastfeeding.",
            sideEffects = "Muscarinic: Sinus bradycardia, nodal rhythms, asystole, bronchoconstriction, increased bronchial and salivary secretions, increased gastrointestinal motility, nausea, vomiting, abdominal cramps, miosis, diaphoresis. Nicotinic: Fasciculations, muscle cramps.",
            priceNpr = "NPR 25.00 - 45.00 per ampoule (0.5 mg/mL: 1 mL / 5 mL)",
            priceInr = "INR 15.00 - 30.00 per ampoule",
            brandsNepal = listOf(
                BrandInfo("Prostigmin-NPL", "Nepal Pharmaceuticals Lab", "Injection", "0.5 mg/mL (1 mL / 5 mL)"),
                BrandInfo("Tigan", "Quest Pharmaceuticals", "Injection", "0.5 mg/mL (1 mL)"),
                BrandInfo("Neostig-DJ", "Deurali-Janta Pharmaceuticals", "Injection", "0.5 mg/mL (1 mL)")
            ),
            brandsIndia = listOf(
