                BrandInfo("Myostigmin", "Neon Laboratories", "Injection", "0.5 mg/mL (1 mL / 5 mL)"),
                BrandInfo("Neomate", "Troikaa Pharmaceuticals", "Injection", "0.5 mg/mL (1 mL)")
            ),
            adultDose = "Reversal: 0.04-0.05 mg/kg IV (max 5 mg) combined with Glycopyrrolate 0.01 mg/kg or Atropine 0.02 mg/kg.",
            childDose = "Reversal: 0.04-0.05 mg/kg IV combined with Atropine 0.02 mg/kg.",
            contraindications = "Mechanical gastrointestinal or urinary tract obstruction; peritonitis; known hypersensitivity to neostigmine or bromides; concurrent succinylcholine use.",
            modeOfAction = "Reversibly inhibits acetylcholinesterase enzyme by carbamylating its esteratic site; halts normal enzymatic hydrolysis of acetylcholine at the neuromuscular junction, leading to rapid, massive accumulation of endogenous acetylcholine in the synaptic cleft; acetylcholine competitively displaces non-depolarizing muscle relaxant molecules from the nicotinic receptors, restoring muscle depolarization.",
            interactions = "MUST be co-administered with Glycopyrrolate or Atropine to prevent lethal muscarinic bradycardia. Depolarizing relaxants (Succinylcholine): Neostigmine inhibits plasma cholinesterase and severely PROLONGS succinylcholine paralysis (never give neostigmine before succinylcholine has fully cleared).",
            packSize = "Glass ampoule of 1 mL (0.5 mg/mL) or 5 mL multidose vial (0.5 mg/mL = 2.5 mg)",
