        // 12. Bupivacaine Hydrochloride (Heavy 0.5% & Plain 0.5%)
        Drug(
            id = "d_bupivacaine",
            genericName = "Bupivacaine Hydrochloride (Heavy 0.5% & Plain 0.5%)",
            system = "Anesthesiology & Perioperative",
            drugClass = "Long-Acting Amide Local Anesthetic",
            blackBoxWarning = "CARDIOTOXICITY BLACK BOX WARNING: High lipid solubility and slow dissociation from cardiac sodium channels causes severe, refractory, and potentially fatal cardiotoxicity (ventricular arrhythmias, wide QRS, refractoriness to defibrillation, and electromechanical dissociation) upon accidental intravenous injection. 0.75% OBSTETRIC EPIDURAL BAN: The 0.75% concentration is STRICTLY CONTRAINDICATED in obstetrical epidural anesthesia due to reports of cardiac arrest and maternal death. NOT FOR INTRAVENOUS REGIONAL ANESTHESIA (BIER BLOCK). In accidental toxicity, initiate immediate resuscitation with 20% INTRALIPID.",
            indications = "Subarachnoid Block (Spinal Anesthesia) for lower abdominal, pelvic, urological, orthopedic (hip/knee replacement), and cesarean section procedures (Heavy 0.5% with 8% Dextrose); Epidural Anesthesia and postoperative epidural analgesia (Plain 0.125% to 0.5%); Peripheral Nerve Blocks (Brachial plexus, Femoral, Sciatic, TAP block); Infiltration analgesia.",
            doses = "Subarachnoid Block (Spinal Anesthesia - Heavy 0.5% in 8% Dextrose):\n• Cesarean Section: 1.8 to 2.2 mL (9 to 11 mg) Heavy Bupivacaine ± Fentanyl (15-25 mcg) or preservative-free Morphine (100 mcg) injected at L3-L4 interspace with patient sitting or lateral.\n• Inguinal Hernia / Lower Abdomen: 2.5 to 3.0 mL (12.5 to 15 mg) Heavy Bupivacaine (sensory level T4-T6).\n• Lower Extremity Orthopedic (Hip/Knee/Femur): 2.5 to 3.5 mL (12.5 to 17.5 mg) Heavy Bupivacaine.\n• Perineal / Saddle Block (Hemorrhoids, Anal Fissure, Cystoscopy): 1.0 to 1.5 mL (5 to 7.5 mg) Heavy Bupivacaine injected in sitting position, maintained sitting for 5-10 minutes.\n\nEpidural Anesthesia (Plain 0.5%):\n• Surgical Anesthesia: 10 to 20 mL (50 to 100 mg) Plain 0.5% in 3-5 mL divided aliquots (test dose first with 3 mL 1.5% lidocaine with 1:200,000 epinephrine).\n• Labor Epidural Analgesia: Continuous infusion of 0.0625% to 0.125% with Fentanyl (2 mcg/mL) at 8 to 12 mL/hour.\n\nMAXIMUM SINGLE SAFE DOSE:\n• Plain Bupivacaine: 2.0 mg/kg (absolute maximum 150 mg in adults).\n• With Epinephrine (1:200,000): 2.5 to 3.0 mg/kg (absolute maximum 175-200 mg).",
            administration = "Spinal Anesthesia: Injected into the subarachnoid cerebrospinal fluid space using pencil-point spinal needles (25G or 27G Whitacre or Sprotte preferred over cutting Quincke needles to prevent Post-Dural Puncture Headache). Prior to injection, confirm free aspiration of clear CSF. Epidural / Nerve Block: ALWAYS aspirate for blood or CSF before every single bolus, and administer in small fractionated aliquots of 3 to 5 mL.",
            timing = "Hospital Operating Room / Labor Delivery Suite procedure only (शल्यक्रिया कक्ष वा प्रसूति कक्षमा मात्र दिने).",
            specialInstructions = "BARICITY MATTERS: Heavy 0.5% is hyperbaric (density > CSF due to 80 mg/mL dextrose) and sinks to dependent areas governed by patient positioning and table tilt for the first 15-20 minutes. Plain 0.5% is isobaric (density = CSF) and stays near injection level regardless of table tilt. Have 20% Lipid Emulsion (Intralipid) stocked in every anesthetizing location for LAST rescue.",
            pkPd = "Amide local anesthetic with long butyl chain. High lipid solubility (partition coefficient 28). Highly protein-bound (~95%, primarily to alpha-1-acid glycoprotein). Onset of sensory block in spinal anesthesia: 2-4 minutes; motor block: 3-5 minutes. Duration of surgical spinal anesthesia: 2 to 3.5 hours (extended up to 4-5 hours in peripheral nerve blocks). Extensively metabolized in the liver by CYP3A4 by N-dealkylation to pipecoloxylidide (PPX). Excreted in urine (6% unchanged). Elimination half-life ~2.7 hours in adults.",
            renalAdj = "No dose reduction needed for single-shot spinal/epidural; repeat dosing in CKD requires caution due to metabolite clearance.",
            hepaticAdj = "Cirrhosis reduces hepatic clearance and decreases alpha-1-acid glycoprotein synthesis (increases free toxic fraction); reduce total doses for peripheral nerve blocks.",
            pregnancy = "Category C. 0.75% is strictly contraindicated for obstetric epidural. Highly bound to maternal proteins, minimizing fetal transfer; widely used and first-line for spinal anesthesia in Cesarean delivery (0.5% Heavy). Hormonal and anatomical changes in pregnancy decrease required spinal dose by ~25-30% due to engorged epidural veins compressing subarachnoid space.",
            lactation = "Safe during breastfeeding; negligible amounts transferred to milk.",
            sideEffects = "High Spinal / Total Spinal (profound hypotension, bradycardia, respiratory arrest from phrenic nerve C3-C5 paralysis), arterial hypotension (due to preganglionic sympathetic vasoconstrictor blockade, managed with IV fluids, Ephedrine, Phenylephrine), shivering, urinary retention, Post-Dural Puncture Headache (PDPH), pruritus (if intrathecal opioids added), Local Anesthetic Systemic Toxicity (LAST: perioral numbness, tinnitus, seizures, ventricular tachycardia, refractory asystole).",
