                BrandInfo("Lipofundin MCT/LCT", "B. Braun", "Emulsion for Inj", "20% (250 mL / 500 mL)"),
                BrandInfo("Smoflipid", "Fresenius Kabi", "Emulsion for Inj", "20% (250 mL)")
            ),
            adultDose = "LAST: 1.5 mL/kg IV bolus over 1 min, then 0.25 mL/kg/min infusion (max 12 mL/kg).",
            childDose = "LAST: 1.5 mL/kg IV bolus over 1 min, then 0.25 mL/kg/min infusion.",
            contraindications = "Severe egg, soybean, or peanut allergy (relative in life-threatening LAST cardiac arrest); severe hyperlipidemia / lipid nephrosis.",
            modeOfAction = "Acts primarily as a 'Lipid Sink' partition buffer, extracting lipid-soluble local anesthetics directly from target tissues (myocardium and brain) into a circulating lipid emulsion compartment; simultaneously drives fatty acid substrate oxidation in cardiac mitochondria and restores myocyte bioenergetics.",
            interactions = "Compatible with standard ACLS fluids. Incompatible with high-dose epinephrine (>1 mcg/kg), which blunts lipid rescue efficacy.",
            packSize = "Glass bottle or flexible plastic bag of 100 mL, 250 mL, or 500 mL (20% lipid emulsion). Store at 2°C to 25°C. Do not freeze.",
