            sideEffects = "Profound respiratory depression, dose-dependent bradycardia (central vagal stimulation), chest wall rigidity ('wooden chest'), post-operative nausea and vomiting (PONV), pruritus (common with intrathecal/epidural use, treated with ondansetron or nalbuphine), urinary retention, biliary spasm (sphincter of Oddi contraction), miosis, mild hypotension.",
            priceNpr = "NPR 110.00 - 180.00 per 2mL ampoule (50 mcg/mL = 100 mcg)",
