        // 18. Midazolam
        Drug(
            id = "d_midazolam",
            genericName = "Midazolam",
            system = "Anesthesiology & Perioperative",
            drugClass = "Short-Acting Benzodiazepine / Imidazobenzodiazepine / Anxiolytic-Sedative-Amnestic",
            blackBoxWarning = "Administer only in settings with continuous monitoring of respiratory and cardiac function and equipment for airway management, resuscitation, and the specific reversal agent FLUMAZENIL. Respiratory depression, airway obstruction, and arrest can occur, especially when combined with opioids or in elderly/debilitated patients.",
            indications = "Pre-operative anxiolysis, sedation, and anterograde amnesia prior to induction of anesthesia or diagnostic/therapeutic procedures (endoscopy, cardioversion, catheterization); Component of balanced anesthesia; Sedation for mechanically ventilated ICU patients; Emergency control of status epilepticus.",
            doses = "Pre-operative Sedation / Anxiolysis (IV):\n• Healthy Adult (<60y): 0.5 to 2.0 mg IV slowly over 2 minutes (titrate in 0.5-1 mg increments; typical total dose 1-2.5 mg).\n• Elderly / Debilitated / ASA III-IV: 0.5 to 1.0 mg IV slowly (maximum total dose rarely exceeds 1.5 mg).\n• Pediatric (Pre-medication): Oral: 0.25 to 0.5 mg/kg PO (mixed with syrup, max 10-15 mg) 30 min before procedure; IV: 0.05 to 0.1 mg/kg IV.\n\nProcedural Conscious Sedation:\n• Initial: 1 to 2 mg IV over 2 min, repeated in 1 mg increments q2-3 min prn until speech slurs and eyelid droop (Ramsay score 3).\n\nICU Sedation in Mechanically Ventilated Patients:\n• Loading: 0.03 to 0.1 mg/kg IV over 2-3 min, followed by continuous infusion 0.03 to 0.2 mg/kg/hour (2 to 10 mg/hour) titrated to RASS -2.",
            administration = "Administer IV slowly over at least 2 minutes. Wait 2-3 minutes between incremental doses to assess clinical peak effect. May be administered IM, intranasally (0.2 mg/kg with atomizer), or orally (mixed in sweet syrup to disguise bitter taste). Water-soluble at pH <4 (imidazole ring open); becomes highly lipid-soluble at physiological pH 7.4 (ring closes).",
            timing = "Operating Room / Pre-op holding area / Endoscopy / ICU administration (शल्यक्रिया अगाडि वा प्रक्रियाको समयमा दिने).",
            specialInstructions = "Flumazenil (0.2 mg IV over 15 seconds, repeated up to 1-2 mg) is the specific reversal agent; note flumazenil half-life (45-60 min) is shorter than midazolam (1.5-2.5h), so monitor for resedation. Paradoxical excitation/agitation occurs in <1% (treat with physostigmine or propofol, avoid more midazolam).",
            pkPd = "Rapid onset of action (IV 1-2 min, peak amnesia 5-10 min). Duration of sedation ~30-60 min for single dose. High plasma protein binding (~96-98%). Extensively metabolized by hepatic CYP3A4 to 1-hydroxymidazolam (active metabolite; undergoes rapid glucuronidation and excreted in urine). Elimination half-life ~1.5 to 2.5 hours (prolonged to 4-10h in elderly, obese, and septic ICU patients).",
            renalAdj = "Reduce dose by 25-50% in severe renal impairment; active 1-hydroxymidazolam glucuronide accumulates and causes prolonged sedation.",
            hepaticAdj = "Cirrhosis reduces clearance and prolongs half-life twofold; cut doses by 50% and titrate cautiously.",
