            adultDose = "Pre-op sedation: 0.5-2.0 mg IV slowly. Sedation infusion: 0.03-0.2 mg/kg/hr. Status epilepticus: 10 mg IM/IV.",
            childDose = "Pre-medication: 0.25-0.5 mg/kg PO or 0.05-0.1 mg/kg IV. Status epilepticus: 0.2 mg/kg IM/nasal.",
            contraindications = "Known hypersensitivity to benzodiazepines; acute narrow-angle glaucoma; severe respiratory insufficiency or acute respiratory depression without artificial ventilation; myasthenia gravis.",
            modeOfAction = "Allosteric modulator at the GABA-A receptor complex, binding to the benzodiazepine site between alpha-1/alpha-2 and gamma-2 subunits, enhancing the opening frequency of GABA-gated chloride channels, causing neuronal hyperpolarization and widespread central nervous system depression.",
